System.assertNotEquals(null, listLocator);
Object rowsObject = rows;
Database.QueryLocator objectLocator = Database.getQueryLocator(rowsObject);
System.assertNotEquals(null, objectLocator);
Database.QueryLocator objectAccessLocator = Database.getQueryLocator(rowsObject, AccessLevel.SYSTEM_MODE);
